class Solution {
    public int[] countRectangles(int[][] rectangles,int[][] points){
        List<Integer>[] widths=new List[101];
        for(int i=0;i<=100;i++)widths[i]=new ArrayList<>();
        for(int[] rectangle:rectangles)widths[rectangle[1]].add(rectangle[0]);
        for(List<Integer> bucket:widths)Collections.sort(bucket);
        int[] answer=new int[points.length];
        for(int p=0;p<points.length;p++)for(int height=points[p][1];height<=100;height++){
            List<Integer> bucket=widths[height];
            int left=0,right=bucket.size();
            while(left<right){
                int middle=(left+right)/2;
                if(bucket.get(middle)<points[p][0])left=middle+1;
                else right=middle;
            }
            answer[p]+=bucket.size()-left;
        }
        return answer;
    }
}

