class Solution {
    public:vector<int> countRectangles(vector<vector<int>>& rectangles,vector<vector<int>>& points){
        vector<vector<int>> widths(101);
        for(auto& rectangle:rectangles)widths[rectangle[1]].push_back(rectangle[0]);
        for(auto& bucket:widths)sort(bucket.begin(),bucket.end());
        vector<int> answer;
        for(auto& point:points){
            int count=0;
            for(int height=point[1];height<=100;++height){
                auto& bucket=widths[height];
                count+=bucket.end()-lower_bound(bucket.begin(),bucket.end(),point[0]);
            }
            answer.push_back(count);
        }
        return answer;
    }
};
